from taf.hw.optical_switch.devices import (
    agiltron,
    calient,
    hbte,
    leoni,
    mitron,
    polatis,
    viavi,
)
from taf.hw.optical_switch.exceptions import DeviceNotSupported


class OpticalSwitchVendor:
    def __init__(self, models):
        self.available_models = models

    def get_model(self, model):
        try:
            model = model.upper()
            optical_switch_model = self.available_models[model]
            return optical_switch_model
        except KeyError:
            raise DeviceNotSupported(f"Model {model} is not supported")


class SupportedOpticalSwitchVendors:

    LEONI = OpticalSwitchVendor(
        {
            "MOL 6X(2X6)": leoni.Leoni_mol_6x_2x6,
            "MOL 2X(1X8)": leoni.Leoni_mol_2x_1x8,
            "MOL 12X(2X12)": leoni.Leoni_mol_12x_2x12,
            "MOL 8X(3X8)": leoni.Leoni_mol_8x_3x8,
            "MOL 5X(2X6)": leoni.Leoni_mol_5x_2x6,
            "MOL 2X(3X8)": leoni.Leoni_mol_2x_3x8,
            "MOL 10X(1X2)": leoni.Leoni_mol_10x_1x2,
            "MOL 2X(4X8)": leoni.Leoni_mol_2x_4x8,
            "MOL 2X(2X12)": leoni.Leoni_mol_2x_2x12,
        }
    )
    CALIENT = OpticalSwitchVendor({"S320": calient.CalientS320})
    MITRON = OpticalSwitchVendor(
        {"OXC1000-32X32-SM-1356-DD-50-LP": mitron.MitronOXC100032X32SM1356DD50LP}
    )
    VIAVI = OpticalSwitchVendor({"MAP200": viavi.Viavi_Map200})
    HBTE = OpticalSwitchVendor({"D4_4": hbte.Hbte_D4_4})
    POLATIS = OpticalSwitchVendor(
        {
            "N-OST-16X16-LU1-DMHNS": polatis.POLATISOXCNOST1616LU1DMHNS,
            "N-OST-32X32-LU1-DMHNS": polatis.POLATISOXCNOST3232LU1DMHNS,
            "N-OST-64X64-LU1-DMWNS": polatis.POLATISOXCNOST6464LU1DMWNS,
        }
    )
    AGILTRON = OpticalSwitchVendor({"OSW-1X2": agiltron.Agiltron})

    @classmethod
    def get_vendor(cls, vendor):
        try:
            vendor_type = getattr(cls, vendor.upper())
            return vendor_type
        except AttributeError:
            raise DeviceNotSupported(f"Vendor {vendor} is not supported")
